/**
 * Block texture atlas (R2627): one layer per tile of TILE_NAMES in two array textures, albedo (sRGB) and material
 * (normal x/y, roughness, metalness; linear). The texels are generated by textures.ts at 64 x 64 per face; nothing is
 * loaded from files and nothing comes from another game (AGENTS 4.11, docs/15).
 *
 * The start-up builds it one tile per step (atlasSteps) so the main thread is handed back between tiles.
 */
import { TILE_NAMES, type TileName } from './blocks.js';
import { TEX_PX, paintTile } from './textures.js';

export const TILE_PX = TEX_PX;
const S = TILE_PX;

export interface AtlasPixels {
  /** RGBA sRGB albedo, layer-major: layer i occupies [i*S*S*4, (i+1)*S*S*4) */
  albedo: Uint8Array<ArrayBuffer>;
  /** RGBA linear: normal x, normal y (128 = 0), roughness, metalness; same layout */
  material: Uint8Array<ArrayBuffer>;
}

/** Both atlases one tile per step, so the start-up can hand frames back between tiles (no long main-thread task). */
export function* atlasMaterialSteps(): Generator<void, AtlasPixels> {
  const layerBytes = S * S * 4;
  const albedo = new Uint8Array(layerBytes * TILE_NAMES.length);
  const material = new Uint8Array(layerBytes * TILE_NAMES.length);
  for (let i = 0; i < TILE_NAMES.length; i++) {
    paintTile(TILE_NAMES[i] as TileName, i * 31 + 7, albedo, material, i * layerBytes);
    yield;
  }
  return { albedo, material };
}

/** Albedo texels for all tiles (icons, showroom colours, tests). */
export function buildAtlasPixels(): Uint8Array<ArrayBuffer> {
  const steps = atlasMaterialSteps();
  for (;;) {
    const r = steps.next();
    if (r.done) return r.value.albedo;
  }
}

/** Average color of a tile (for particles, debris, icons), 0..1 per channel; holes (alpha < 0.5) are skipped. */
export function tileAverageColor(pixels: Uint8Array, layer: number): [number, number, number] {
  const layerBytes = S * S * 4;
  let r = 0;
  let g = 0;
  let b = 0;
  let n = 0;
  for (let i = layer * layerBytes; i < (layer + 1) * layerBytes; i += 4) {
    if (pixels[i + 3]! < 128) continue;
    r += pixels[i]!;
    g += pixels[i + 1]!;
    b += pixels[i + 2]!;
    n++;
  }
  if (n === 0) return [1, 1, 1];
  return [r / n / 255, g / n / 255, b / n / 255];
}
